package ads

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestGetAll(t *testing.T) {
	testRepo := NewAdsRepository()

	results := testRepo.GetAll()

	// 10 mock ads are now generated by the constructor
	assert.Len(t, results, 10)

	// Check the first mock ad properties match the new data
	got := results[0]

	assert.Equal(t, int(1), got.ID)
	assert.Equal(t, "MacBook Pro 16 M1 Max", got.Title)
	assert.Equal(t, "Отличное состояние, полный комплект, использовался для программирования.", got.Description)
	assert.Equal(t, 250000, got.Price)
	assert.ElementsMatch(t, []string{"ноутбук", "apple", "macbook", "электроника"}, got.Tags)
	assert.NotZero(t, got.CreatedAt)
	assert.Equal(t, int(1), got.SellerID)
	assert.Equal(t, int(150), got.Views)
}
